head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71201";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71201.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_explainShow_onclick
 * @description 「Ⅰ. 발행증권에 관한사항」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_explainShow_onclick = function(e){
    try {
        scwin.explainShow(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71201.btn_explainShow_onclick' }); }
};

/**
 * @method
 * @name btn_explainShow_2_onclick
 * @description 「Ⅱ. 상장신청인에 관한 사항」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_explainShow_2_onclick = function(e){
    try {
        scwin.explainShow(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71201.btn_explainShow_2_onclick' }); }
};

/**
 * @method
 * @name btn_explainShow_3_onclick
 * @description 「Ⅲ. 기타사항」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_explainShow_3_onclick = function(e){
    try {
        scwin.explainShow(3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71201.btn_explainShow_3_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name explainShow
 * @description explain Show 처리
 * @param {*} num num
 * @returns {void}
 * @hidden N
 */
scwin.explainShow = function (num) {
    const info1 = $c.util.getComponent('txt_etnInfo1');
    const info2 = $c.util.getComponent('txt_etnInfo2');
    const info3 = $c.util.getComponent('txt_etnInfo3');
    if (num === 0) {
        (!info1 ? console.warn('[sdd] 표시 전환 대상 미해결: info1') : (('none') === 'none' ? (info1.hide ? info1.hide() : void 0) : (info1.show ? info1.show() : void 0)));
        (!info2 ? console.warn('[sdd] 표시 전환 대상 미해결: info2') : (('none') === 'none' ? (info2.hide ? info2.hide() : void 0) : (info2.show ? info2.show() : void 0)));
        (!info3 ? console.warn('[sdd] 표시 전환 대상 미해결: info3') : (('none') === 'none' ? (info3.hide ? info3.hide() : void 0) : (info3.show ? info3.show() : void 0)));
    } else {
        if (num === 1) {
            (!info1 ? console.warn('[sdd] 표시 전환 대상 미해결: info1') : (('block') === 'none' ? (info1.hide ? info1.hide() : void 0) : (info1.show ? info1.show() : void 0)));
            (!info2 ? console.warn('[sdd] 표시 전환 대상 미해결: info2') : (('none') === 'none' ? (info2.hide ? info2.hide() : void 0) : (info2.show ? info2.show() : void 0)));
            (!info3 ? console.warn('[sdd] 표시 전환 대상 미해결: info3') : (('none') === 'none' ? (info3.hide ? info3.hide() : void 0) : (info3.show ? info3.show() : void 0)));
        } else {
            if (num === 2) {
                (!info1 ? console.warn('[sdd] 표시 전환 대상 미해결: info1') : (('none') === 'none' ? (info1.hide ? info1.hide() : void 0) : (info1.show ? info1.show() : void 0)));
                (!info2 ? console.warn('[sdd] 표시 전환 대상 미해결: info2') : (('block') === 'none' ? (info2.hide ? info2.hide() : void 0) : (info2.show ? info2.show() : void 0)));
                (!info3 ? console.warn('[sdd] 표시 전환 대상 미해결: info3') : (('none') === 'none' ? (info3.hide ? info3.hide() : void 0) : (info3.show ? info3.show() : void 0)));
            } else {
                if (num === 3) {
                    (!info1 ? console.warn('[sdd] 표시 전환 대상 미해결: info1') : (('none') === 'none' ? (info1.hide ? info1.hide() : void 0) : (info1.show ? info1.show() : void 0)));
                    (!info2 ? console.warn('[sdd] 표시 전환 대상 미해결: info2') : (('none') === 'none' ? (info2.hide ? info2.hide() : void 0) : (info2.show ? info2.show() : void 0)));
                    (!info3 ? console.warn('[sdd] 표시 전환 대상 미해결: info3') : (('block') === 'none' ? (info3.hide ? info3.hide() : void 0) : (info3.show ? info3.show() : void 0)));
                }
            }
        }
    }
};
